//! 📐️ CAD layers, block ownership and nine independently typed entity geometries.
use crate::standards::v1::subsets::base::schema::snapshot::sqlite::native::Bound;
use semio_framework_os_kernel::sqlite_snapshot::artifact::{FloatColumn,FloatRow as SqliteRow,insert_ieee754,insert_key_ieee754};
use super::{SemioCadSnapshot,CadLayer,CadBlock,CadEntityRecord,CadEntity,SemioPoint2};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{artifact::{Cell,Projection,reconstruct_text},validate_sqlite_database_schema,SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase}};
use std::collections::{BTreeMap,BTreeSet};
fn number(value:usize)->Result<i64,String>{i64::try_from(value).map_err(|error|error.to_string())}
fn identity<'a>(row:impl std::borrow::Borrow<SqliteRow<'a>>,columns:usize)->Result<(),String>{let row=*row.borrow();if row.rowid<=0||row.integer(0)?!=row.rowid||row.values.len()!=columns{Err("invalid Semio CAD row identity or columns".into())}else{Ok(())}}
fn boolean(value:i64)->Result<bool,String>{match value{0=>Ok(false),1=>Ok(true),_=>Err("invalid Semio CAD boolean".into())}}
fn optional_integer(row:SqliteRow<'_>,index:usize)->Result<Option<i64>,String>{if row.is_null(index)?{Ok(None)}else{row.integer(index).map(Some)}}
fn ordered<'a>(mut rows:Vec<SqliteRow<'a>>,column:usize)->Result<Vec<SqliteRow<'a>>,String>{rows.sort_by_key(|row|row.integer(column).unwrap_or(-1));for(ordinal,row)in rows.iter().enumerate(){if row.integer(column)?!=number(ordinal)?{return Err("Semio CAD ordinals must be contiguous".into());}}Ok(rows)}
fn details<'a>(db:&'a SqliteDatabase,table:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,SqliteRow<'a>>,String>{let mut result=BTreeMap::new();for(count,row)in float_rows(db,table,control)?.into_iter().enumerate(){identity(row,columns)?;if result.insert(row.rowid,row).is_some(){return Err("duplicate Semio CAD row identity".into());}if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn point(row:SqliteRow<'_>,x:usize)->Result<SemioPoint2,String>{Ok(SemioPoint2{x:row.real(x)?,y:row.real(x+1)?})}
fn project_record(record:&CadEntityRecord,block:Option<i64>,ordinal:usize,layers:&BTreeMap<&str,i64>,blocks:&BTreeMap<&str,i64>,p:&mut Projection<'_,'_>)->Result<(),String>{
let kind=match record.entity{CadEntity::Line{..}=>"line",CadEntity::Arc{..}=>"arc",CadEntity::Circle{..}=>"circle",CadEntity::Ellipse{..}=>"ellipse",CadEntity::Polyline{..}=>"polyline",CadEntity::Text{..}=>"text",CadEntity::Insert{..}=>"insert",CadEntity::Solid{..}=>"solid",CadEntity::Dimension{..}=>"dimension"};let id=p.insert_float("semio_cad_entity",&[Cell::Integer(1),block.map(Cell::Integer).unwrap_or(Cell::Null),Cell::Integer(number(ordinal)?),Cell::Text(&record.handle),Cell::Integer(*layers.get(record.layer.as_str()).ok_or("dangling Semio CAD layer")?),Cell::Text(kind)])?;
match &record.entity{
CadEntity::Line{a,b}=>p.insert_key_float("semio_cad_line",id,&[Cell::Real(a.x),Cell::Real(a.y),Cell::Real(b.x),Cell::Real(b.y)])?,
CadEntity::Arc{center,radius,start_angle,end_angle}=>p.insert_key_float("semio_cad_arc",id,&[Cell::Real(center.x),Cell::Real(center.y),Cell::Real(*radius),Cell::Real(*start_angle),Cell::Real(*end_angle)])?,
CadEntity::Circle{center,radius}=>p.insert_key_float("semio_cad_circle",id,&[Cell::Real(center.x),Cell::Real(center.y),Cell::Real(*radius)])?,
CadEntity::Ellipse{center,major_axis_end,ratio,start_param,end_param}=>p.insert_key_float("semio_cad_ellipse",id,&[Cell::Real(center.x),Cell::Real(center.y),Cell::Real(major_axis_end.x),Cell::Real(major_axis_end.y),Cell::Real(*ratio),Cell::Real(*start_param),Cell::Real(*end_param)])?,
CadEntity::Polyline{vertices,closed}=>{p.insert_key_float("semio_cad_polyline",id,&[Cell::Integer(i64::from(*closed))])?;for(ordinal,vertex)in vertices.iter().enumerate(){p.insert_float("semio_cad_polyline_vertex",&[Cell::Integer(id),Cell::Integer(number(ordinal)?),Cell::Real(vertex.x),Cell::Real(vertex.y)])?;}},
CadEntity::Text{position,height,rotation,content}=>p.insert_key_float("semio_cad_text",id,&[Cell::Real(position.x),Cell::Real(position.y),Cell::Real(*height),Cell::Real(*rotation),Cell::Text(content)])?,
CadEntity::Insert{block_name,insertion_point,scale,rotation}=>p.insert_key_float("semio_cad_insert",id,&[Cell::Integer(*blocks.get(block_name.as_str()).ok_or("dangling Semio CAD inserted block")?),Cell::Real(insertion_point.x),Cell::Real(insertion_point.y),Cell::Real(scale.x),Cell::Real(scale.y),Cell::Real(*rotation)])?,
CadEntity::Solid{p1,p2,p3,p4}=>p.insert_key_float("semio_cad_solid",id,&[Cell::Real(p1.x),Cell::Real(p1.y),Cell::Real(p2.x),Cell::Real(p2.y),Cell::Real(p3.x),Cell::Real(p3.y),Cell::Real(p4.x),Cell::Real(p4.y)])?,
CadEntity::Dimension{def_point,text_position,measurement,text}=>p.insert_key_float("semio_cad_dimension",id,&[Cell::Real(def_point.x),Cell::Real(def_point.y),Cell::Real(text_position.x),Cell::Real(text_position.y),Cell::Real(*measurement),Cell::Text(text)])?}
Ok(())}
impl ArtifactSqliteSnapshot for SemioCadSnapshot{
fn preflight_sqlite_snapshot_encoding(&self,_encoding:semio_framework_os_kernel::sqlite_snapshot::SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),String>{let mut b=Bound::new("",control)?;self.native_fields(&mut b)?;b.finish()}

fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1)?;
if dialect.artifact_kind!="s.stdio.semio"||dialect.standard!="v1"||(dialect.subset!="*"&&dialect.subset!="cad"){return Err(String::from("Semio owned snapshot dialect differs from its dedicated semantic subset").into());}
let row=database.table("semio_cad_document")?.single_row()?;
if row.rowid!=1||row.integer(0)?!=1||row.text(1)?!=self.schema{return Err(String::from("Semio owned document identity differs from projected semantic fields").into());}
control.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}

const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,String>{
let mut p=Projection::new(Self::SQLITE_SCHEMA,control)?;p.insert_key_float("semio_cad_document",1,&[Cell::Text(&self.schema)])?;let mut layers=BTreeMap::new();for(ordinal,layer)in self.layers.iter().enumerate(){let id=p.insert_float("semio_cad_layer",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&layer.name),Cell::Integer(i64::from(layer.color_index)),Cell::Text(&layer.line_type),Cell::Integer(i64::from(layer.visible))])?;if layers.insert(layer.name.as_str(),id).is_some(){return Err("duplicate Semio CAD layer name".into());}}let mut blocks=BTreeMap::new();for(ordinal,block)in self.blocks.iter().enumerate(){let id=p.insert_float("semio_cad_block",&[Cell::Integer(1),Cell::Integer(number(ordinal)?),Cell::Text(&block.name),Cell::Real(block.base_point.x),Cell::Real(block.base_point.y)])?;if blocks.insert(block.name.as_str(),id).is_some(){return Err("duplicate Semio CAD block name".into());}}
for block in &self.blocks{let mut handles=BTreeSet::new();for(ordinal,entity)in block.entities.iter().enumerate(){if !handles.insert(entity.handle.as_str()){return Err("duplicate Semio CAD entity handle within block".into());}project_record(entity,Some(blocks[block.name.as_str()]),ordinal,&layers,&blocks,&mut p)?;}}let mut handles=BTreeSet::new();for(ordinal,entity)in self.entities.iter().enumerate(){if !handles.insert(entity.handle.as_str()){return Err("duplicate Semio CAD document entity handle".into());}project_record(entity,None,ordinal,&layers,&blocks,&mut p)?;}p.finish()
}
fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,String> { Self::reconstruct_sqlite_database(database, control, Self::SQLITE_SCHEMA) }
}

impl SemioCadSnapshot {
    /// 🧩️ Restores the owned typed subset inside its independently declared relational composition.
    pub fn reconstruct_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>, declared_schema: &str)->Result<Self,String> {

control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;validate_sqlite_database_schema(database,declared_schema,control.limits()).map_err(|error|error.to_string())?;let document=single_float_row(database,"semio_cad_document")?;identity(document,2)?;if document.rowid!=1{return Err("invalid Semio CAD document identifier".into());}let mut completed=0usize;
let mut layers=Vec::new();let mut layer_names=BTreeMap::new();let mut names=BTreeSet::new();for row in ordered_float_rows(database,"semio_cad_layer",2,control)?{identity(row,7)?;if row.integer(1)?!=1||layer_names.insert(row.rowid,row.text(3)?).is_some()||!names.insert(row.text(3)?){return Err("invalid Semio CAD layer ownership or identity".into());}layers.push(CadLayer{name:reconstruct_text(control,row.text(3)?)?,color_index:i32::try_from(row.integer(4)?).map_err(|error|error.to_string())?,line_type:reconstruct_text(control,row.text(5)?)?,visible:boolean(row.integer(6)?)?});}
let block_rows=ordered_float_rows(database,"semio_cad_block",2,control)?;let mut block_names=BTreeMap::new();let mut names=BTreeSet::new();for row in &block_rows{identity(row,6)?;if row.integer(1)?!=1||block_names.insert(row.rowid,row.text(3)?).is_some()||!names.insert(row.text(3)?){return Err("invalid Semio CAD block ownership or identity".into());}}
let mut lines=details(database,"semio_cad_line",5,control)?;let mut arcs=details(database,"semio_cad_arc",6,control)?;let mut circles=details(database,"semio_cad_circle",4,control)?;let mut ellipses=details(database,"semio_cad_ellipse",8,control)?;let mut polylines=details(database,"semio_cad_polyline",2,control)?;let mut texts=details(database,"semio_cad_text",6,control)?;let mut inserts=details(database,"semio_cad_insert",7,control)?;let mut solids=details(database,"semio_cad_solid",9,control)?;let mut dimensions=details(database,"semio_cad_dimension",7,control)?;
let mut vertices=BTreeMap::<i64,Vec<SqliteRow<'_>>>::new();let mut ids=BTreeSet::new();for row in float_rows(database,"semio_cad_polyline_vertex",control)?{identity(row,5)?;if !polylines.contains_key(&row.integer(1)?)||!ids.insert(row.rowid){return Err("invalid Semio CAD polyline vertex owner or identity".into());}row.integer(2)?;vertices.entry(row.integer(1)?).or_default().push(row);completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}
let mut entities=BTreeMap::<Option<i64>,Vec<SqliteRow<'_>>>::new();let mut ids=BTreeSet::new();for row in float_rows(database,"semio_cad_entity",control)?{identity(row,7)?;let owner=optional_integer(row,2)?;if row.integer(1)?!=1||owner.is_some_and(|id|!block_names.contains_key(&id))||!ids.insert(row.rowid){return Err("invalid Semio CAD entity ownership or identity".into());}row.integer(3)?;entities.entry(owner).or_default().push(row);}
let mut native_entities=BTreeMap::<Option<i64>,Vec<CadEntityRecord>>::new();for(owner,rows)in entities{let mut records=Vec::new();let mut handles=BTreeSet::new();for row in ordered(rows,3)?{if !handles.insert(row.text(4)?){return Err("duplicate Semio CAD entity handle within owner".into());}let entity=match row.text(6)?{
"line"=>{let r=lines.remove(&row.rowid).ok_or("missing CAD line fields")?;CadEntity::Line{a:point(r,1)?,b:point(r,3)?}},
"arc"=>{let r=arcs.remove(&row.rowid).ok_or("missing CAD arc fields")?;CadEntity::Arc{center:point(r,1)?,radius:r.real(3)?,start_angle:r.real(4)?,end_angle:r.real(5)?}},
"circle"=>{let r=circles.remove(&row.rowid).ok_or("missing CAD circle fields")?;CadEntity::Circle{center:point(r,1)?,radius:r.real(3)?}},
"ellipse"=>{let r=ellipses.remove(&row.rowid).ok_or("missing CAD ellipse fields")?;CadEntity::Ellipse{center:point(r,1)?,major_axis_end:point(r,3)?,ratio:r.real(5)?,start_param:r.real(6)?,end_param:r.real(7)?}},
"polyline"=>{let r=polylines.remove(&row.rowid).ok_or("missing CAD polyline fields")?;let mut native_vertices=Vec::new();for vertex in ordered(vertices.remove(&row.rowid).unwrap_or_default(),2)?{native_vertices.push(point(vertex,3)?);completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}CadEntity::Polyline{vertices:native_vertices,closed:boolean(r.integer(1)?)?}},
"text"=>{let r=texts.remove(&row.rowid).ok_or("missing CAD text fields")?;CadEntity::Text{position:point(r,1)?,height:r.real(3)?,rotation:r.real(4)?,content:reconstruct_text(control,r.text(5)?)?}},
"insert"=>{let r=inserts.remove(&row.rowid).ok_or("missing CAD insert fields")?;CadEntity::Insert{block_name:reconstruct_text(control,block_names.get(&r.integer(1)?).ok_or("dangling CAD inserted block")?)?,insertion_point:point(r,2)?,scale:point(r,4)?,rotation:r.real(6)?}},
"solid"=>{let r=solids.remove(&row.rowid).ok_or("missing CAD solid fields")?;CadEntity::Solid{p1:point(r,1)?,p2:point(r,3)?,p3:point(r,5)?,p4:point(r,7)?}},
"dimension"=>{let r=dimensions.remove(&row.rowid).ok_or("missing CAD dimension fields")?;CadEntity::Dimension{def_point:point(r,1)?,text_position:point(r,3)?,measurement:r.real(5)?,text:reconstruct_text(control,r.text(6)?)?}},_=>return Err("unknown Semio CAD entity kind".into())};records.push(CadEntityRecord{handle:reconstruct_text(control,row.text(4)?)?,layer:reconstruct_text(control,layer_names.get(&row.integer(5)?).ok_or("dangling CAD entity layer")?)?,entity});completed+=1;if completed%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,0)?;}}native_entities.insert(owner,records);}
if !lines.is_empty()||!arcs.is_empty()||!circles.is_empty()||!ellipses.is_empty()||!polylines.is_empty()||!texts.is_empty()||!inserts.is_empty()||!solids.is_empty()||!dimensions.is_empty()||!vertices.is_empty(){return Err("orphan or contradictory Semio CAD variant detail".into());}let entities=native_entities.remove(&None).unwrap_or_default();let mut blocks=Vec::new();for row in block_rows{blocks.push(CadBlock{name:reconstruct_text(control,row.text(3)?)?,base_point:point(row,4)?,entities:native_entities.remove(&Some(row.rowid)).unwrap_or_default()});}control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,completed,completed)?;Ok(Self{schema:reconstruct_text(control,document.text(1)?)?,layers,blocks,entities})
    }
}

fn float_columns(table:&str)->&'static [FloatColumn]{match table{"semio_cad_block"=>&[FloatColumn::Binary64(4),FloatColumn::Binary64(5)],"semio_cad_line"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_cad_arc"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)],"semio_cad_circle"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3)],"semio_cad_ellipse"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7)],"semio_cad_polyline_vertex"=>&[FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_cad_text"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4)],"semio_cad_insert"=>&[FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6)],"semio_cad_solid"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8)],"semio_cad_dimension"=>&[FloatColumn::Binary64(1),FloatColumn::Binary64(2),FloatColumn::Binary64(3),FloatColumn::Binary64(4),FloatColumn::Binary64(5)],_=>&[]}}
trait FloatProjection { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>; fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>; }
impl FloatProjection for Projection<'_,'_> { fn insert_float(&mut self,table:&str,cells:&[Cell<'_>])->Result<i64,String>{insert_ieee754(self,table,cells,float_columns(table))} fn insert_key_float(&mut self,table:&str,key:i64,cells:&[Cell<'_>])->Result<(),String>{insert_key_ieee754(self,table,key,cells,float_columns(table))} }
fn float_rows<'a>(db:&'a SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let table_rows=db.table(table)?;control.check_rows(table_rows.rows.len())?;control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,0,table_rows.rows.len())?;let mut result=Vec::new();for(count,row)in table_rows.rows.iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,table_rows.rows.len())?;}}Ok(result)}
fn ordered_float_rows<'a>(db:&'a SqliteDatabase,table:&str,ordinal:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<SqliteRow<'a>>,String>{let mut result=Vec::new();for(count,row)in semio_framework_os_kernel::sqlite_snapshot::artifact::ordered_row_refs(db.table(table)?,ordinal,control)?.into_iter().enumerate(){result.push(SqliteRow::new(row,float_columns(table))?);if count%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,count,0)?;}}Ok(result)}
fn single_float_row<'a>(db:&'a SqliteDatabase,table:&str)->Result<SqliteRow<'a>,String>{SqliteRow::new(db.table(table)?.single_row()?,float_columns(table))}

impl SemioCadSnapshot{
/// 📏️ Bounds explicitly owned native fields before encoding.
pub fn native_fields(&self,b:&mut Bound<'_,'_>)->Result<(),String>{b.text(&self.schema)?;b.entities(self.layers.len())?;for layer in &self.layers{b.text(&layer.name)?;b.text(&layer.line_type)?;b.scalars(2)?;}b.entities(self.blocks.len())?;for block in &self.blocks{b.text(&block.name)?;b.scalars(2)?;native_entities(&block.entities,b)?;}native_entities(&self.entities,b)?;Ok(())}
}

fn native_entities(records:&[CadEntityRecord],b:&mut Bound<'_, '_>)->Result<(),String>{b.entities(records.len())?;for record in records{b.text(&record.handle)?;b.text(&record.layer)?;match &record.entity{CadEntity::Line{..}=>b.scalars(4)?,CadEntity::Arc{..}=>b.scalars(5)?,CadEntity::Circle{..}=>b.scalars(3)?,CadEntity::Ellipse{..}=>b.scalars(7)?,CadEntity::Polyline{vertices,..}=>{b.entities(vertices.len())?;b.scalars(vertices.len().checked_mul(2).ok_or("CAD native point count overflow")?)?;b.scalars(1)?;},CadEntity::Text{content,..}=>{b.text(content)?;b.scalars(4)?;},CadEntity::Insert{block_name,..}=>{b.text(block_name)?;b.scalars(5)?;},CadEntity::Solid{..}=>b.scalars(8)?,CadEntity::Dimension{text,..}=>{b.text(text)?;b.scalars(5)?;}}}Ok(())}
